d-template-columns:repeat(5,1fr);gap:8px;margin:21px 0}.tab{border:1px solid var(--line);background:#0d121a;color:#9caabd;border-radius:14px;padding:13px 9px;font-weight:900;cursor:pointer;transition:.2s}.tab.active{color:white;border-color:transparent;background:linear-gradient(135deg,#7048e8,#0b91a7);box-shadow:0 12px 32px rgba(112,72,232,.22)}.card{border:1px solid var(--line);background:rgba(17,21,29,.95);border-radius:22px;padding:20px;box-shadow:0 15px 48px rgba(0,0,0,.22)}.card h3{font-size:18px;margin:0 0 5px}.sub{font-size:11px;line-height:1.55;color:var(--muted)}.grid{display:grid;grid-template-columns:1.03fr .97fr;gap:18px}.phone{max-width:430px;margin:17px auto 0;background:#05070b;border:1px solid #313948;border-radius:35px;padding:10px;box-shadow:0 28px 75px rgba(0,0,0,.5)}.notchwrap{height:31px;display:grid;place-items:center}.notch{width:108px;height:18px;background:#020304;border-radius:999px}.screen{min-height:590px;border-radius:26px;overflow:hidden;background:linear-gradient(180deg,#111923,#091019)}.wahead{display:flex;align-items:center;gap:10px;padding:13px 14px;background:#101d28;border-bottom:1px solid rgba(255,255,255,.05)}.avatar{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,#7c3aed,#06b6d4);font-weight:950}.wahead b{font-size:13px}.wahead small{display:block;color:#73e7aa;font-size:10px;margin-top:2px}.chat{min-height:485px;padding:16px 12px;display:flex;flex-direction:column;gap:9px}.msg{max-width:88%;font-size:12px;line-height:1.48;padding:10px 11px;border-radius:12px;box-shadow:0 4px 12px rgba(0,0,0,.16)}.in{background:#1b2938;border-top-left-radius:3px}.out{background:#145d4f;align-self:flex-end;border-top-right-radius:3px}.time{display:block;font-size:9px;color:#8fa1b7;text-align:right;margin-top:4px}.composer{padding:10px;border-top:1px solid rgba(255,255,255,.06)}.start,.primary,.softbtn{width:100%;border-radius:12px;padding:13px;font-weight:900;cursor:pointer}.start{border:1px solid #3c4a61;background:#142235;color:#f3f7fb}.primary{border:0;color:white;background:linear-gradient(135deg,#7c3aed,#0891b2);margin-top:10px}.softbtn{border:1px solid #344257;background:#121c2b;color:#cbd9e8}.steps{display:grid;gap:9px;margin-top:16px}.step{display:flex;gap:11px;align-items:center;border:1px solid var(--line);background:#0c141f;border-radius:13px;padding:11px}.dot{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#172235;color:#778da8;font-size:10px;font-weight:950;flex:0 0 auto}.step strong{font-size:11px;display:block}.step span{display:block;color:var(--muted);font-size:10px;margin-top:2px}.step.active{border-color:#6e5fe8;background:rgba(139,92,246,.08)}.step.done .dot{background:rgba(52,211,153,.15);color:#79e6b2}.quote{display:none;margin-top:14px;border:1px solid rgba(52,211,153,.28);background:linear-gradient(145deg,rgba(52,211,153,.08),rgba(139,92,246,.05));border-radius:17px;padding:16px}.quote.show{display:block}.price{font-size:37px;font-weight:950;letter-spacing:-.04em;margin:6px 0}.studio{display:grid;grid-template-columns:.88fr 1.12fr;gap:18px}.mockbox{border:1px solid var(--line);background:radial-gradient(circle at 50% 35%,#1b2330 0,#0c1118 70%);border-radius:22px;min-height:570px;display:grid;place-items:center;padding:18px;position:relative;overflow:hidden}.shirtwrap{position:relative;width:min(390px,88vw);aspect-ratio:1/1}.shirtwrap svg{width:100%;height:100%;filter:drop-shadow(0 26px 22px rgba(0,0,0,.32))}.logoPreview{position:absolute;left:50%;top:42%;transform:translate(-50%,-50%);width:82px;height:82px;object-fit:contain;display:none;filter:drop-shadow(0 3px 4px rgba(0,0,0,.2))}.logoText{position:absolute;left:50%;top:42%;transform:translate(-50%,-50%);font-size:14px;font-weight:950;letter-spacing:.05em;color:#10131a;background:#fff;padding:8px 10px;border-radius:8px;box-shadow:0 6px 20px rgba(0,0,0,.18)}.studioControls{display:grid;gap:12px}.control{border:1px solid var(--line);background:#0c141f;border-radius:14px;padding:13px}.control label{display:block;font-size:10px;color:#9aa8ba;font-weight:850;margin-bottom:8px}.control input,.control select{width:100%;background:#121c2b;border:1px solid #334056;color:white;border-radius:10px;padding:10px;outline:none}.swatches{display:flex;gap:9px;flex-wrap:wrap}.swatch{width:34px;height:34px;border-radius:10px;border:2px solid transparent;cursor:pointer;box-shadow:inset 0 0 0 1px rgba(255,255,255,.15)}.swatch.active{border-color:#fff}.uploadZone{border:1px dashed #485a73;background:#101928;border-radius:14px;padding:16px;text-align:center;font-size:11px;color:#b7c4d4}.uploadZone input{display:none}.uploadZone label{cursor:pointer;font-weight:900;color:#dce7f4}.mockStatus{margin-top:10px;border:1px solid rgba(52,211,153,.25);background:rgba(52,211,153,.07);color:#baf4d6;border-radius:12px;padding:10px 12px;font-size:10px;display:none}.mockStatus.show{display:block}.formgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:11px;margin-top:14px}.field{border:1px solid var(--line);background:#0c141f;border-radius:13px;padding:12px}.field label{display:block;font-size:9px;color:#98a6b8;font-weight:850;margin-bottom:7px}.field input,.field select{width:100%;border:0;outline:0;background:transparent;color:white;font-weight:850}.calc{margin-top:14px;border:1px solid rgba(139,92,246,.28);background:rgba(139,92,246,.06);border-radius:16px;padding:15px}.calcrow{display:flex;justify-content:space-between;gap:12px;font-size:11px;color:#bac5d2;margin-bottom:8px}.calcrow.total{font-size:18px;color:white;font-weight:950;border-top:1px solid rgba(255,255,255,.08);padding-top:9px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px}.kpi{border:1px solid var(--line);background:#0c141f;border-radius:15px;padding:15px}.kpi b{font-size:25px;display:block}.kpi span{font-size:9px;color:var(--muted)}.pipeline{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;overflow:auto}.stage{min-width:175px;border:1px solid var(--line);background:#0b131e;border-radius:15px;padding:11px}.stage h4{font-size:10px;color:#aab8ca;margin:0 0 9px}.order{border:1px solid #2c394e;background:#111b29;border-radius:11px;padding:9px;margin-bottom:7px}.order:last-child{margin-bottom:0}.order b{font-size:10px}.order small{font-size:9px;color:#8fa1b7;line-height:1.4;display:block;margin-top:3px}.tag{display:inline-block;margin-top:6px;border-radius:7px;padding:5px 7px;font-size:8px;font-weight:950}.tv{background:rgba(139,92,246,.14);color:#c4b5fd}.tc{background:rgba(34,211,238,.12);color:#a5f3fc}.tg{background:rgba(52,211,153,.12);color:#bbf7d0}.dashboardGrid{display:grid;grid-template-columns:1.2fr .8fr;gap:17px}.activity{display:grid;gap:8px;margin-top:13px}.activityItem{display:flex;justify-content:space-between;gap:12px;border:1px solid var(--line);background:#0c141f;border-radius:12px;padding:11px}.activityItem b{font-size:10px}.activityItem span{font-size:9px;color:var(--muted)}.bar{height:8px;background:#1a2534;border-radius:999px;overflow:hidden;margin-top:8px}.bar i{height:100%;display:block;background:linear-gradient(90deg,#8b5cf6,#22d3ee);border-radius:999px}.notice{margin-top:18px;border:1px solid rgba(251,191,36,.22);background:rgba(251,191,36,.06);color:#ead7a1;border-radius:13px;padding:13px 14px;font-size:9px;line-height:1.55}.hidden{display:none}.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%) translateY(18px);background:white;color:#07101a;border-radius:12px;padding:11px 15px;font-size:10px;font-weight:900;opacity:0;pointer-events:none;transition:.22s;z-index:50;box-shadow:0 18px 50px rgba(0,0,0,.3)}.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}
